// Standalone Android probe: genuine codec fixture, SQLite and public services.
// Build with: flutter build apk --debug -t tool/probes/s5_offline_probe.dart
// ignore_for_file: avoid_print
import 'dart:convert';
import 'dart:io';

import 'package:crypto/crypto.dart';
import 'package:flutter/material.dart';
import 'package:ia_music/adapters/cover_fetch_adapter.dart';
import 'package:ia_music/data/daos.dart';
import 'package:ia_music/data/ia_database.dart';
import 'package:ia_music/data/tables.dart';
import 'package:ia_music/library/cover_chain.dart';
import 'package:ia_music/ui/shared/cover_art.dart';
import 'package:path_provider/path_provider.dart';

// Exact bytes of test/fixtures/library_smoke/探曲03.mp3, generated by ffmpeg.
const _realAudio =
    '';

void main() {
  WidgetsFlutterBinding.ensureInitialized();
  runApp(const MaterialApp(home: _Probe()));
}

class _Probe extends StatefulWidget {
  const _Probe();
  @override
  State<_Probe> createState() => _ProbeState();
}

class _ProbeState extends State<_Probe> {
  String _result = '真实封面链运行中…';
  DataAccess? _data;
  CoverChain? _chain;
  int? _id;
  File? _audio;
  CoverFetchAdapter? _fetch;
  int _attempt = 0;

  @override
  void initState() {
    super.initState();
    _run();
  }

  Future<void> _run() async {
    try {
      final parent = await getApplicationSupportDirectory();
      final dir = await parent.createTemp('s5_cover_');
      final original = base64Decode(_realAudio);
      final audio = await File('${dir.path}/Imagine.mp3')
          .writeAsBytes(original);
      final db = (await openIaDatabaseMemory()).db;
      final data = DataAccess(db);
      final root = await db
          .into(db.repositoryRoots)
          .insert(
            RepositoryRootsCompanion.insert(
              path: dir.path,
              mode: RepositoryMode.directory,
              addedAt: 1,
            ),
          );
      final id = await data.library.insertTrackWithIndex(
        root,
        'Imagine.mp3',
        mtime: 1,
        fileSize: original.length,
        contentHash: sha256.convert(original).toString(),
        nowMs: 1,
        title: 'Imagine',
        artistDisplay: 'John Lennon',
      );
      const probeProxy = String.fromEnvironment('S5_HTTP_PROXY');
      final fetch = CoverFetchAdapter(
        proxy: probeProxy.isEmpty ? null : probeProxy,
      );
      final chain = CoverChain(data, fetch);
      final watch = Stopwatch()..start();
      final result = await chain.decide(id);
      final report = {
        'sqliteVersion':
            (await db
                    .customSelect('SELECT sqlite_version() AS version')
                    .getSingle())
                .read<String>('version'),
        'kind': result.kind.name,
        'elapsedMs': watch.elapsedMilliseconds,
        'requests': fetch.requestCount,
        'responses': fetch.responses
            .map((r) => '${r.uri.host}:${r.statusCode}')
            .toList(),
        'coverExists': await File('${audio.path}.cover.jpg').exists(),
        'audioUnchanged':
            sha256.convert(await audio.readAsBytes()).toString() ==
            sha256.convert(original).toString(),
        'registeredKind': (await data.library.rowById(id))?.coverKind?.name,
      };
      final encoded = jsonEncode(report);
      await File('${parent.path}/s5_probe_result.json').writeAsString(encoded);
      print('S5_PROBE_RESULT $encoded');
      if (mounted) {
        setState(() {
          _result = encoded;
          _data = data;
          _chain = chain;
          _id = id;
          _audio = audio;
          _fetch = fetch;
        });
      }
    } catch (error, stack) {
      print('S5_PROBE_ERROR $error\n$stack');
      if (mounted) setState(() => _result = 'ERROR: $error');
    }
  }

  Future<void> _retry() async {
    final row = await _data!.library.rowById(_id!);
    final result = await _chain!.decide(_id!);
    final report = {
      'kind': result.kind.name,
      'requests': _fetch!.requestCount,
      'responses': _fetch!.responses
          .map((r) => '${r.uri.host}:${r.statusCode}')
          .toList(),
      'coverExists': await File('${_audio!.path}.cover.jpg').exists(),
      'audioUnchanged':
          sha256.convert(await _audio!.readAsBytes()).toString() ==
          row!.contentHash,
      'registeredKind': (await _data!.library.rowById(_id!))?.coverKind?.name,
      'sameTrackId': _id,
    };
    final encoded = jsonEncode(report);
    print('S5_PROBE_RETRY $encoded');
    final parent = await getApplicationSupportDirectory();
    await File('${parent.path}/s5_probe_retry.json').writeAsString(encoded);
    if (mounted) {
      setState(() {
        _result = encoded;
        _attempt++;
      });
    }
  }

  @override
  Widget build(BuildContext context) => Scaffold(
    appBar: AppBar(title: const Text('S5 真实网络探针')),
    body: Padding(
      padding: const EdgeInsets.all(24),
      child: Column(
        children: [
          if (_id != null)
            CoverArt(
              key: ValueKey(_attempt),
              trackId: _id!,
              title: 'Imagine',
              data: _data!,
              chain: _chain,
              size: 180,
            ),
          const SizedBox(height: 24),
          Text(_result),
          TextButton(
            onPressed: _id == null ? null : _retry,
            child: const Text('重新检查封面'),
          ),
        ],
      ),
    ),
  );
}
